package com.bananalab.lite;
import java.nio.file.*;import java.io.*;import java.util.*;import org.json.*;
public final class Stage61FullTransformerCheck{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static BananaTransformer load(Path r)throws Exception{return Stage56TrainingCheck.model(r);}
 static TransformerTraining.Tensor tensor(TransformerTraining.Tape t,float[][] matrix){for(TransformerTraining.Tensor p:t.params)if(p.v==matrix||(p.v.length==1&&matrix.length==1&&p.v[0]==matrix[0]))return p;throw new AssertionError("parameter missing");}
 public static void main(String[] args)throws Exception{Path r=Paths.get(args[0]);BananaTransformer m=load(r);JSONObject example=new JSONObject().put("question","hola").put("answer","hola !");TransformerTraining.Sequence seq=TransformerTraining.sequence(m,example);TransformerTraining.Tape tape=new TransformerTraining.Tape();TransformerTraining.Tensor out=TransformerTraining.forward(m,tape,seq.input);BananaTransformer.Session session=m.session();double error=0;for(int i=0;i<seq.input.length;i++){float[] logits=session.step(seq.input[i]);for(int j=0;j<logits.length;j++)error=Math.max(error,Math.abs(logits[j]-out.v[i][j]));}check(error<.0001,"full forward matches incremental causal inference "+error);TransformerTraining.loss(out,seq.labels,true);tape.backward();
 List<float[][]> groups=new ArrayList<>();groups.add(m.embedding);groups.add(m.position);for(BananaTransformer.Block b:m.blocks){groups.add(b.qkv);groups.add(b.o);groups.add(b.f1);groups.add(b.f2);groups.add(new float[][]{b.n1w});groups.add(new float[][]{b.n1b});groups.add(new float[][]{b.n2w});groups.add(new float[][]{b.n2b});}groups.add(m.head);groups.add(new float[][]{m.normWeight});groups.add(new float[][]{m.normBias});groups.add(new float[][]{m.headBias});int checked=0;for(float[][] weights:groups){TransformerTraining.Tensor p=tensor(tape,weights);int ai=0,aj=0;float max=0;for(int i=0;i<p.g.length;i++)for(int j=0;j<p.g[i].length;j++)if(Math.abs(p.g[i][j])>max){max=Math.abs(p.g[i][j]);ai=i;aj=j;}check(max>0,"nonzero gradient group "+checked);float original=weights[ai][aj],epsilon=.002f;weights[ai][aj]=original+epsilon;double plus=TransformerTraining.loss(TransformerTraining.forward(m,new TransformerTraining.Tape(),seq.input),seq.labels,false);weights[ai][aj]=original-epsilon;double minus=TransformerTraining.loss(TransformerTraining.forward(m,new TransformerTraining.Tape(),seq.input),seq.labels,false);weights[ai][aj]=original;double numerical=(plus-minus)/(2*epsilon);check(Math.abs(numerical-p.g[ai][aj])<.003+Math.abs(numerical)*.08,"gradient "+checked+": "+p.g[ai][aj]+" != "+numerical);checked++;}
 m=load(r);float[][] before=TransformerTraining.snapshot(m);float[][] emb=HeadTrainer.copy(m.embedding);float[][][] q=new float[m.layers][][];for(int l=0;l<m.layers;l++)q[l]=HeadTrainer.copy(m.blocks[l].qkv);JSONArray train=NeuralTraining.defaultRows("train"),eval=NeuralTraining.defaultRows("eval"),anchor=NeuralTraining.defaultRows("anchor");float[][] expected=HeadTrainer.distributions(NeuralTraining.tokens(m,anchor),m.head,m.headBias);double old=TransformerTraining.evaluate(m,eval);TransformerTraining.train(m,train,anchor);double next=TransformerTraining.evaluate(m,eval),kl=HeadTrainer.divergence(NeuralTraining.tokens(m,anchor),expected,m.head,m.headBias);check(next<old-1e-5&&kl<=.003,"complete model evaluation and retention "+old+" -> "+next+" KL "+kl);check(HeadTrainer.distance(emb,m.embedding)>0,"embeddings trained");for(int l=0;l<m.layers;l++)check(HeadTrainer.distance(q[l],m.blocks[l].qkv)>0,"attention trained block "+l);check(TransformerTraining.distance(m,before)<=.01001,"global trust region");ByteArrayOutputStream bytes=new ByteArrayOutputStream();m.save(bytes);BananaTransformer reopened=new BananaTransformer(new ByteArrayInputStream(bytes.toByteArray()),Files.newInputStream(r.resolve("assets/chat34/vocab.txt")),Files.newInputStream(r.resolve("assets/chat34/tokenizer.json")));check(Math.abs(TransformerTraining.evaluate(reopened,eval)-next)<1e-7,"checkpoint reload exact evaluation");Files.write(r.resolve("test/resources/chat61-full-candidate.bin"),bytes.toByteArray());JSONObject report=new JSONObject().put("before",old).put("after",next).put("anchorKL",kl).put("delta",TransformerTraining.distance(m,before)).put("gradientGroups",checked).put("forwardMaxError",error);Files.write(r.resolve("test/resources/training61-report.json"),report.toString(2).getBytes("UTF-8"));System.out.println("PASS Stage61 full Transformer gradients, causal forward parity, all3 attention blocks, embeddings, checkpoint and retention "+report);}
}
